using System;
using System.IO;
using System.Drawing;
using System.Diagnostics;
using System.Reflection;
using System.Windows.Forms;
using Microsoft.Win32;
namespace OverdriveSetup {
 static class Setup {
  static string Target { get { return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Overdrive"); } }
  static void Extract(string resource,string target){using(var src=Assembly.GetExecutingAssembly().GetManifestResourceStream(resource)){if(src==null)throw new Exception("Installer file missing: "+resource);using(var dst=File.Create(target))src.CopyTo(dst);}}
  static void Install(string dir,bool shortcuts){Directory.CreateDirectory(dir);Extract("Overdrive.exe",Path.Combine(dir,"Overdrive.exe"));Extract("Overdrive.exe.config",Path.Combine(dir,"Overdrive.exe.config"));if(!shortcuts)return;string self=Path.Combine(dir,"Overdrive-Setup.exe");File.Copy(Application.ExecutablePath,self,true);var shell=Type.GetTypeFromProgID("WScript.Shell");dynamic ws=Activator.CreateInstance(shell);string link=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Overdrive.lnk");dynamic shortcut=ws.CreateShortcut(link);shortcut.TargetPath=Path.Combine(dir,"Overdrive.exe");shortcut.WorkingDirectory=dir;shortcut.Description="Overdrive Windows optimizer";shortcut.Save();using(var k=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\Overdrive")){k.SetValue("DisplayName","OVERDRIVE");k.SetValue("DisplayVersion","0.1.0");k.SetValue("Publisher","Suleiman Alnsour");k.SetValue("UninstallString","\""+self+"\" --uninstall");k.SetValue("InstallLocation",dir);k.SetValue("NoModify",1,RegistryValueKind.DWord);k.SetValue("NoRepair",1,RegistryValueKind.DWord);}}
  [STAThread]static int Main(string[] args){try{if(args.Length==2&&args[0]=="--test-extract"){Install(args[1],false);return 0;}Application.EnableVisualStyles();if(args.Length==1&&args[0]=="--uninstall"){string link=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Overdrive.lnk");if(File.Exists(link))File.Delete(link);foreach(string name in new[]{"Overdrive.exe","Overdrive.exe.config"}){string file=Path.Combine(Target,name);if(File.Exists(file))File.Delete(file);}Registry.CurrentUser.DeleteSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\Overdrive",false);MessageBox.Show("OVERDRIVE was removed. Your saved settings reports are still on this PC.","OVERDRIVE");return 0;}using(var form=new Form{Text="Install OVERDRIVE",ClientSize=new Size(490,250),StartPosition=FormStartPosition.CenterScreen,BackColor=Color.FromArgb(8,10,13),ForeColor=Color.White,Font=new Font("Segoe UI",10),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false}){form.Controls.Add(new Label{Text="OVERDRIVE",Location=new Point(25,25),Size=new Size(430,50),Font=new Font("Segoe UI",24,FontStyle.Bold)});form.Controls.Add(new Label{Text="Install for this Windows account. Open the app when setup is done.",Location=new Point(29,90),Size=new Size(425,54)});var button=new Button{Text="INSTALL",Location=new Point(29,165),Size=new Size(210,48),BackColor=Color.FromArgb(168,216,255),ForeColor=Color.Black,FlatStyle=FlatStyle.Flat};button.Click+=(s,e)=>{try{Install(Target,true);MessageBox.Show("Installed. Find OVERDRIVE in the Start menu.","OVERDRIVE");form.Close();}catch(Exception ex){MessageBox.Show(ex.Message,"Install failed");}};form.Controls.Add(button);Application.Run(form);}return 0;}catch(Exception e){MessageBox.Show(e.Message,"OVERDRIVE setup");return 1;}}
 }
}
